$ErrorActionPreference='Stop'
Write-Host 'STORM: LEVEL200; GRADE20; AIZVER SPELI; TIKAI TESTA VM 192.168.56.101'
$code=[Text.Encoding]::ASCII.GetString([Convert]::FromBase64String(''))
$lines=@($code | ssh root@192.168.56.101 python3 - --apply)
$exit=$LASTEXITCODE
$lines | ForEach-Object { Write-Host $_ }
if($exit -ne 0 -or !($lines | Select-String -SimpleMatch 'STORM_LEVEL_GRADE_CONFIRMED;','STORM_LEVEL_GRADE_ALREADY_GRANTED;')){throw 'STORM_LEVEL_GRADE_NOT_CONFIRMED; ATSUTI_IZVADI'}
